import type { CodegenConfig } from "@graphql-codegen/cli";

// Typed GraphQL documents for the product page, from the API's schema (contracts/schema.graphql, generated by the
// API). No GraphQL client library: src/lib/graphql.ts posts the typed document with fetch.
const config: CodegenConfig = {
  schema: "../../contracts/schema.graphql",
  documents: ["src/**/*.{ts,tsx}", "!src/gql/**/*"],
  generates: { "src/gql/": { preset: "client", config: { scalars: { UUID: "string" }, documentMode: "string" } } },
  ignoreNoDocuments: true,
};

export default config;
